int main() {
    // 使用大顶堆优先队列模拟
    priority_queue<int> pq;
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) {
        int tmp;
        cin >> tmp;
        pq.push(tmp);
    }
    // 模拟
    while (pq.size() >= 3) {
        int z = pq.top();
        pq.pop();
        int y = pq.top();
        pq.pop();
        int x = pq.top();
        pq.pop();

        if (x == y && y != z) {
            pq.push(z-y);
        }  else if (x != y && y == z) {
            pq.push(y-x);
        } else if(x != y && y != z){
            pq.push(max(y-x, z-y) - min(y-x, z-y));
        }
    }
    // 为空直接输出0
    if (pq.empty()) {
        cout << 0;
    // 剩余 1 2 输出较大重量    
    } else {
        cout << pq.top();
    }
    return 0;
}

