        Scanner in = new Scanner(System.in);
        // 使用大顶堆优先队列模拟
        PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
        int n = in.nextInt();
        for (int i = 0; i < n; i++) {
            pq.add(in.nextInt());
        }
        in.close();
​
        // 模拟
        while (pq.size() >= 3) {
            int z = pq.poll();
            int y = pq.poll();
            int x = pq.poll();
​
            if (x == y && y != z) {
                pq.add(z - y);
            } else if (x != y && y == z) {
                pq.add(y - x);
            } else if (x != y && y != z) {
                pq.add(Math.abs((y - x) - (z - y)));
            }
        }
​
        // 为空直接输出0
        if (pq.isEmpty()) {
            System.out.println(0);
        // 剩余 1 2 输出较大重量
        } else {
            System.out.println(pq.peek());
        }
    }
