package main
​
import (
    "container/heap"
    "fmt"
)
​
// 大顶堆实现
type MaxHeap []int
​
func (h MaxHeap) Len() int            { return len(h) }
func (h MaxHeap) Less(i, j int) bool  { return h[i] > h[j] }
func (h MaxHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *MaxHeap) Push(x interface{}) { *h = append(*h, x.(int)) }
func (h *MaxHeap) Pop() interface{} {
    old := *h
    n := len(old)
    x := old[n-1]
    *h = old[:n-1]
    return x
}
​
func main() {
    var n int
    fmt.Scan(&n)
    h := &MaxHeap{}
    for i := 0; i < n; i++ {
        var tmp int
        fmt.Scan(&tmp)
        heap.Push(h, tmp)
    }
    heap.Init(h)
​
    // 模拟
    for h.Len() >= 3 {
        z := heap.Pop(h).(int)
        y := heap.Pop(h).(int)
        x := heap.Pop(h).(int)
​
        if x == y && y != z {
            heap.Push(h, z-y)
        } else if x != y && y == z {
            heap.Push(h, y-x)
        } else if x != y && y != z {
            diff := (y - x) - (z - y)
            if diff < 0 {
                diff = -diff
            }
            heap.Push(h, diff)
        }
    }
​
    // 为空直接输出0
    if h.Len() == 0 {
        fmt.Println(0)
    // 剩余 1 2 输出较大重量
    } else {
        fmt.Println((*h)[0])
    }
}
